1	import type {ChatSession} from '../types/session.js';
2	import type {ToolRegistry, ToolContext, ToolResponse} from './tools/registry.js';
3	import type {
4	  AIProvider,
5	  AccumulatedUsageMetadata,
6	  Message,
7	  MessageChunk,
8	  SendMessageParams,
9	  ToolCall,
10	  ToolResultContent,
11	  UsageMetadata,
12	} from '../types/ai.js';
13	import type {OutgoingMessage} from '../types/messages.js';
14	import type {PromptBuilder, PromptBuilderOptions} from '../infrastructure/builders/promptBuilder.js';
15	import type {SessionStore} from '../types/sessionStore.js';
16	import {toMessages, createContextConfig} from './conversationContext.js';
17	import type {ContextConfig} from './conversationContext.js';
18	import {
19	  shouldContinueToolLoop,
20	  collectText,
21	  buildToolCallMessages,
22	  collectToolCalls,
23	  extractStopReason,
24	  extractUsage,
25	  accumulateUsage,
26	} from './orchestratorHelpers.js';
27	import {appendEntry, commitStreamingEntries} from './entryMutations.js';
28	import {log} from '../shared/logger.js';
29	
30	const DEFAULT_MAX_TOOL_ROUNDS = 5;
31	
32	export interface OrchestratorHooks {
33	  beforeSession?: (session: ChatSession) => Promise<void>;
34	  afterSession?: (session: ChatSession) => Promise<void>;
35	  beforeUserInput?: (session: ChatSession, userMessage: string) => Promise<string>;
36	  afterUserInput?: (session: ChatSession, userMessage: string) => Promise<void>;
37	  beforeModelResponse?: (session: ChatSession, systemPrompt: string) => Promise<string>;
38	  afterModelResponse?: (session: ChatSession, responseText: string, usage?: AccumulatedUsageMetadata) => Promise<void>;
39	  onError?: (session: ChatSession, error: Error) => Promise<void>;
40	  /** The supported seam for an EU AI Act Art. 14 human-oversight control: fires before each known tool's executor, and a returned ToolResponse replaces the call (see docs/adding-a-tool.md); it receives the model's raw tool input and, through session, the caller's authHeaders, so a policy that logs either logs personal data and credential material; the engine asserts nothing about any policy installed here. */
41	  beforeToolCall?: (session: ChatSession, call: ToolCall) => Promise<ToolResponse | undefined>;
42	  /** Fires when the model asks for a tool round the budget refuses, after the last provider call and before afterModelResponse; a returned string reaches the user as the turn's closing text, and the engine writes none of its own (see specs/hal-engine-tool-budget/spec.md). */
43	  onToolBudgetExhausted?: (session: ChatSession, budget: ToolBudgetInfo) => Promise<string | undefined>;
44	}
45	
46	export interface ToolBudgetInfo {
47	  maxToolRounds: number;
48	  requestedTools: string[];
49	}
50	
51	type BeforeToolCall = NonNullable<OrchestratorHooks['beforeToolCall']>;
52	type OnToolBudgetExhausted = NonNullable<OrchestratorHooks['onToolBudgetExhausted']>;
53	
54	export const TOOL_BUDGET_EXHAUSTED = 'tool_budget_exhausted';
55	
56	export interface ChatOrchestrator {
57	  processMessage(session: ChatSession): Promise<string>;
58	  processMessageStream(session: ChatSession): AsyncGenerator<MessageChunk>;
59	}
60	
61	export interface ChatOrchestratorOptions {
62	  maxToolRounds?: number;
63	  contextConfig?: Partial<ContextConfig>;
64	  promptBuilderOptions?: PromptBuilderOptions;
65	  hooks?: OrchestratorHooks;
66	  sessionStore?: SessionStore;
67	}
68	
69	interface ToolExecutionResult {
70	  clientMessages: OutgoingMessage[];
71	  suppressOutput: boolean;
72	}
73	export function createChatOrchestrator(
74	  provider: AIProvider,
75	  promptBuilder: PromptBuilder,
76	  toolRegistry?: ToolRegistry,
77	  options?: ChatOrchestratorOptions
78	): ChatOrchestrator {
79	  const maxToolRounds = normalizeToolRounds(options?.maxToolRounds);
80	  const contextConfig = createContextConfig(options?.contextConfig);
81	  const toolInstructions = toolRegistry?.getPromptInstructions();
82	  const baseSystemPrompt = promptBuilder.build({...options?.promptBuilderOptions, toolInstructions});
83	  const tools = toolRegistry?.getDefinitions();
84	  const hooks = options?.hooks;
85	  const sessionStore = options?.sessionStore;
86	
87	  return {
88	    async processMessage(session: ChatSession): Promise<string> {
89	      return collectText(this.processMessageStream(session));
90	    },
91	
92	    async *processMessageStream(session: ChatSession): AsyncGenerator<MessageChunk> {
93	      try {
94	        if (hooks?.beforeSession) await hooks.beforeSession(session);
95	
96	        let userMessage = lastUserContent(session);
97	
98	        if (hooks?.beforeUserInput) {
99	          userMessage = await rewriteUserMessage(session, userMessage, hooks.beforeUserInput);
100	        }
101	
102	        if (hooks?.afterUserInput) await hooks.afterUserInput(session, userMessage);
103	
104	        const systemPrompt = hooks?.beforeModelResponse
105	          ? await hooks.beforeModelResponse(session, baseSystemPrompt)
106	          : baseSystemPrompt;
107	
108	        const messages: Message[] = toMessages(session.entries, contextConfig);
109	        const roundUsages: (UsageMetadata | undefined)[] = [];
110	        let responseText = '';
111	
112	        // Bounded by the budget gate below, not the header: maxToolRounds executed rounds, maxToolRounds + 1 provider calls.
113	        for (let round = 0; ; round++) {
114	          log.info('orchestrator', 'starting round', {round});
115	          const pendingToolCalls: ToolCall[] = [];
116	
117	          const outcome = yield* streamRound(provider, {messages, systemPrompt, tools}, pendingToolCalls);
118	          responseText += outcome.text;
119	          roundUsages.push(outcome.usage);
120	
121	          if (!shouldContinueToolLoop(outcome.stopReason, pendingToolCalls, toolRegistry)) break;
122	          if (budgetSpent(round, maxToolRounds, pendingToolCalls)) {
123	            const budget = {maxToolRounds, requestedTools: pendingToolCalls.map(tc => tc.name)};
124	            responseText += yield* closeExhaustedTurn(session, budget, hooks?.onToolBudgetExhausted);
125	            break;
126	          }
127	
128	          log.info('orchestrator', 'executing tools', {tools: pendingToolCalls.map(tc => tc.name)});
129	          const {clientMessages, suppressOutput} = await executeToolCalls(
130	            pendingToolCalls,
131	            messages,
132	            session,
133	            toolCallRunner(toolRegistry!, session, hooks?.beforeToolCall)
134	          );
135	          log.info('orchestrator', 'tool execution complete', {
136	            clientMessageCount: clientMessages.length,
137	            clientMessageTypes: clientMessages.map(m => m.type),
138	            suppressOutput,
139	          });
140	
141	          if (clientMessages.length > 0) {
142	            yield {type: 'tool_result' as const, clientMessages};
143	          }
144	
145	          if (suppressOutput) {
146	            yield {type: 'suppress_output' as const};
147	          }
148	        }
149	
150	        if (hooks?.afterModelResponse)
151	          await hooks.afterModelResponse(session, responseText, accumulateUsage(roundUsages));
152	      } catch (error) {
153	        if (hooks?.onError && error instanceof Error) {
154	          await hooks.onError(session, error);
155	        }
156	        throw error;
157	      } finally {
158	        // Before both: a provider that threw mid-stream leaves an entry open, and nothing should persist it that way.
159	        commitStreamingEntries(session);
160	        try {
161	          if (hooks?.afterSession) await hooks.afterSession(session);
162	        } finally {
163	          await saveSession(sessionStore, session);
164	        }
165	      }
166	    },
167	  };
168	}
169	
170	// A negative budget means no tool rounds; a non-finite one, NaN included, falls back to the default rather than never ending.
171	function normalizeToolRounds(value: number | undefined): number {
172	  if (value === undefined || !Number.isFinite(value)) return DEFAULT_MAX_TOOL_ROUNDS;
173	  return Math.max(0, Math.floor(value));
174	}
175	
176	// Gates execution, not the provider call: a round nobody can read is never run, and the call that read the last one already has.
177	function budgetSpent(round: number, maxToolRounds: number, pendingToolCalls: ToolCall[]): boolean {
178	  if (round < maxToolRounds) return false;
179	  log.warn('orchestrator', 'tool budget exhausted', {
180	    maxToolRounds,
181	    requestedTools: pendingToolCalls.map(tc => tc.name),
182	  });
183	  return true;
184	}
185	
186	// The stop always follows the text: the round's own stop already committed its entry, and a bare text chunk would open one never committed.
187	async function* closeExhaustedTurn(
188	  session: ChatSession,
189	  budget: ToolBudgetInfo,
190	  hook?: OnToolBudgetExhausted
191	): AsyncGenerator<MessageChunk, string> {
192	  const sentence = (hook ? await hook(session, budget) : undefined) ?? '';
193	  if (sentence !== '') yield {type: 'text', text: sentence};
194	  yield {type: 'stop', stopReason: TOOL_BUDGET_EXHAUSTED};
195	  return sentence;
196	}
197	
198	interface RoundOutcome {
199	  stopReason: string;
200	  text: string;
201	  usage?: UsageMetadata;
202	}
203	
204	// `yield*` in the caller evaluates to this return, so the round's totals come back as data.
205	async function* streamRound(
206	  provider: AIProvider,
207	  request: SendMessageParams,
208	  pendingToolCalls: ToolCall[]
209	): AsyncGenerator<MessageChunk, RoundOutcome> {
210	  let stopReason = '';
211	  let text = '';
212	  let usage: UsageMetadata | undefined;
213	
214	  for await (const chunk of provider.sendMessage(request)) {
215	    yield chunk;
216	    collectToolCalls(chunk, pendingToolCalls);
217	    stopReason = extractStopReason(chunk) ?? stopReason;
218	    usage = extractUsage(chunk) ?? usage;
219	    if (chunk.type === 'text') text += chunk.text;
220	  }
221	
222	  return {stopReason, text, usage};
223	}
224	
225	// A changed message is also written back to the session's last user entry.
226	async function rewriteUserMessage(
227	  session: ChatSession,
228	  userMessage: string,
229	  hook: (session: ChatSession, userMessage: string) => Promise<string>
230	): Promise<string> {
231	  const modified = await hook(session, userMessage);
232	  if (modified === userMessage) return userMessage;
233	
234	  updateLastUserContent(session, modified);
235	  return modified;
236	}
237	
238	function lastUserContent(session: ChatSession): string {
239	  for (let i = session.entries.length - 1; i >= 0; i--) {
240	    const entry = session.entries[i];
241	    if (entry.role === 'user') return entry.content;
242	  }
243	  return '';
244	}
245	
246	function updateLastUserContent(session: ChatSession, content: string): void {
247	  for (let i = session.entries.length - 1; i >= 0; i--) {
248	    const entry = session.entries[i];
249	    if (entry.role === 'user') {
250	      entry.content = content;
251	      return;
252	    }
253	  }
254	}
255	
256	// One runner per round: the policy sees each known call before its executor, and an unknown name keeps the registry's own path.
257	function toolCallRunner(toolRegistry: ToolRegistry, session: ChatSession, beforeToolCall?: BeforeToolCall) {
258	  const context: ToolContext = {
259	    userId: session.userId,
260	    sessionId: session.sessionId,
261	    workspaceId: session.workspaceId,
262	    authHeaders: session.authHeaders,
263	  };
264	
265	  return async (tc: ToolCall): Promise<ToolResponse> => {
266	    const declined =
267	      beforeToolCall && toolRegistry.has(tc.name) ? await consultPolicy(beforeToolCall, session, tc) : undefined;
268	    return declined ?? toolRegistry.execute(tc.name, tc.input, context);
269	  };
270	}
271	
272	// A throwing policy declines its call rather than failing the turn: every tool_use must still be answered.
273	async function consultPolicy(
274	  policy: BeforeToolCall,
275	  session: ChatSession,
276	  tc: ToolCall
277	): Promise<ToolResponse | undefined> {
278	  try {
279	    return await policy(session, tc);
280	  } catch (error) {
281	    log.warn('orchestrator', 'beforeToolCall threw, so the call is declined', {
282	      tool: tc.name,
283	      errorType: error instanceof Error ? error.name : typeof error,
284	    });
285	    return {result: `The ${tc.name} call was declined and not performed.`};
286	  }
287	}
288	
289	async function executeToolCalls(
290	  pendingToolCalls: ToolCall[],
291	  messages: Message[],
292	  session: ChatSession,
293	  runToolCall: (tc: ToolCall) => Promise<ToolResponse>
294	): Promise<ToolExecutionResult> {
295	  messages.push(buildToolCallMessages(pendingToolCalls));
296	
297	  const responses = await Promise.all(
298	    pendingToolCalls.map(async tc => {
299	      const response = await runToolCall(tc);
300	      return {tc, response};
301	    })
302	  );
303	
304	  const toolResults: ToolResultContent[] = responses.map(({tc, response}) => ({
305	    type: 'tool_result' as const,
306	    toolUseId: tc.id,
307	    content: response.result,
308	  }));
309	  messages.push({role: 'user', content: toolResults});
310	
311	  const rawClientMessages = responses.flatMap(({response}) => response.clientMessages ?? []);
312	
313	  return {
314	    clientMessages: assignEntryIndices(rawClientMessages, session),
315	    suppressOutput: responses.some(({response}) => response.suppressAssistantResponse === true),
316	  };
317	}
318	
319	function assignEntryIndices(clientMessages: OutgoingMessage[], session: ChatSession): OutgoingMessage[] {
320	  return clientMessages.map(msg => {
321	    if (msg.type !== 'entry_upsert') return msg;
322	    const index = appendEntry(session, msg.entry);
323	    return {...msg, index};
324	  });
325	}
326	
327	// A store outage is not a reason to fail the turn the customer already received.
328	async function saveSession(store: SessionStore | undefined, session: ChatSession): Promise<void> {
329	  if (!store?.save) return;
330	
331	  try {
332	    await store.save(session);
333	  } catch (error) {
334	    const message = error instanceof Error ? error.message : String(error);
335	    log.error('orchestrator', 'session save failed', {sessionId: session.sessionId, error: message});
336	  }
337	}
